INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$5aae2475$SATQ$, $SATQ$97bbdc34-b086-4b64-bd7e-939f61ee8bc8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Stomata, tiny pore structures in a leaf that absorb gases needed for plant growth, open when guard cells surrounding each pore swell with water. In a pivotal 2007 article, plant cell <span aria-hidden="true">______</span><span class="sr-only">blank</span> showed that lipid molecules called phosphatidylinositol phosphates are responsible for signaling guard cells to open stomata.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"84aeb6be-1fb9-4a57-a01f-14df47112b3f","content":"<p>biologist<span data-ssml-say-as=\"characters\">,</span> Yuree Lee</p>"},{"id":"e9c8f20e-a5b3-4185-beaa-e7e0bb9b8830","content":"<p>biologist Yuree Lee<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"0f0e142f-08f6-48a5-b238-8432ab7f0557","content":"<p>biologist Yuree Lee</p>"},{"id":"301556a0-65b0-4816-8bd5-787be9ec1281","content":"<p>biologist<span data-ssml-say-as=\"characters\">,</span> Yuree Lee<span data-ssml-say-as=\"characters\">,</span></p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["0f0e142f-08f6-48a5-b238-8432ab7f0557"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to offset the proper noun "Yuree Lee" from the title "plant cell biologist" that describes Lee.</p><p>Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice D is incorrect because no punctuation is needed around the proper noun "Yuree Lee." Setting the phrase off with punctuation suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5aae2475","external_id":"97bbdc34-b086-4b64-bd7e-939f61ee8bc8","vaultid":null,"uId":"c2a49e51-e651-4b65-8bde-3e7948edd659","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Stomata, tiny pore structures in a leaf that absorb gases needed for plant growth, open when guard cells surrounding each pore swell with water. In a pivotal 2007 article, plant cell <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> showed that lipid molecules called phosphatidylinositol phosphates are responsible for signaling guard cells to open stomata.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"84aeb6be-1fb9-4a57-a01f-14df47112b3f","content":"<p>biologist<span data-ssml-say-as=\"characters\">,</span> Yuree Lee</p>"},{"id":"e9c8f20e-a5b3-4185-beaa-e7e0bb9b8830","content":"<p>biologist Yuree Lee<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"0f0e142f-08f6-48a5-b238-8432ab7f0557","content":"<p>biologist Yuree Lee</p>"},{"id":"301556a0-65b0-4816-8bd5-787be9ec1281","content":"<p>biologist<span data-ssml-say-as=\"characters\">,</span> Yuree Lee<span data-ssml-say-as=\"characters\">,</span></p>"}],"keys":["0f0e142f-08f6-48a5-b238-8432ab7f0557"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to offset the proper noun \"Yuree Lee\" from the title \"plant cell biologist\" that describes Lee.</p><p>Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice D is incorrect because no punctuation is needed around the proper noun \"Yuree Lee.\" Setting the phrase off with punctuation suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$5ad2a12c$SATQ$, $SATQ$f3097cbc-07dc-4f3f-b5c5-f88623a36c76$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The First Folio, published in 1623, is the first collection of William Shakespeare&rsquo;s plays. The collection <span aria-hidden="true">______</span><span class="sr-only">blank</span> 18 plays that might otherwise have been lost, such as <em>Julius Caesar</em> and <em>Macbeth</em>.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"20e36092-a86d-4ca6-9bdb-d9ca20bc21e5","content":"<p>to be including</p>"},{"id":"4222b38c-2572-47d6-815c-9e9ccc4cbd22","content":"<p>including</p>"},{"id":"35205716-202c-40a9-b256-31d47253d3a7","content":"<p>to include</p>"},{"id":"7aa193c6-dbe5-4dfb-bbee-3fff6baaeb84","content":"<p>includes</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["7aa193c6-dbe5-4dfb-bbee-3fff6baaeb84"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject (in this case, "the collection"), and this choice supplies the finite present tense verb "includes" to indicate what is in the collection.</p><p>Choice A is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive "to be including" doesn&rsquo;t supply the main clause with a finite verb. Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle "including" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive "to include" doesn&rsquo;t supply the main clause with a finite verb.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5ad2a12c","external_id":"f3097cbc-07dc-4f3f-b5c5-f88623a36c76","vaultid":null,"uId":"a7f0d101-ba3c-44d1-acb5-ee9d62541d01","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The First Folio, published in 1623, is the first collection of William Shakespeare&rsquo;s plays. The collection <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> 18 plays that might otherwise have been lost, such as <em>Julius Caesar</em> and <em>Macbeth</em>.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"20e36092-a86d-4ca6-9bdb-d9ca20bc21e5","content":"<p>to be including</p>"},{"id":"4222b38c-2572-47d6-815c-9e9ccc4cbd22","content":"<p>including</p>"},{"id":"35205716-202c-40a9-b256-31d47253d3a7","content":"<p>to include</p>"},{"id":"7aa193c6-dbe5-4dfb-bbee-3fff6baaeb84","content":"<p>includes</p>"}],"keys":["7aa193c6-dbe5-4dfb-bbee-3fff6baaeb84"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject (in this case, \"the collection\"), and this choice supplies the finite present tense verb \"includes\" to indicate what is in the collection.</p><p>Choice A is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive \"to be including\" doesn&rsquo;t supply the main clause with a finite verb. Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle \"including\" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive \"to include\" doesn&rsquo;t supply the main clause with a finite verb.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$5b8f9cf2$SATQ$, $SATQ$3bc3e61e-c2c6-441a-ae74-ecc66e630b95$SATQ$::uuid, $SATQ$ccebe7cb-4a1c-4832-891b-bd53e7c65fab$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In the canon of North African literature, Moroccan author Driss Chra&iuml;bi&rsquo;s 1954 novel <em>The Simple Past</em>&nbsp;(<em>Le Pass&eacute; simple</em>) looms large. A coming-of-age story, a social meditation, and a sober gaze into the dark maw of French colonialism, <span aria-hidden="true">______</span><span class="sr-only">blank</span> interrogates systemic power with memorable intensity.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"875b24e9-6db2-47cf-a232-e45abef0f5df","content":"<p>Morocco gained its independence two years before the publication of Chra&iuml;bi&rsquo;s debut novel, which</p>"},{"id":"d13049f9-1745-4100-a2a7-d03063f8d514","content":"<p>Chra&iuml;bi&rsquo;s debut novel, published two years before Morocco gained its independence,</p>"},{"id":"8d9edecb-7c29-4fc5-a0cc-7e62e591449d","content":"<p>Chra&iuml;bi wrote a debut novel that, published two years before Morocco gained its independence,</p>"},{"id":"27c62977-59ca-42f9-a66a-429bbb992a39","content":"<p>published two years before Morocco gained its independence, Chra&iuml;bi wrote a debut novel that</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["d13049f9-1745-4100-a2a7-d03063f8d514"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. Subject-modifier placement requires a modifier and its subject to be next to each other. The subject of the modifier "a coming-of-age story&hellip;colonialism" is Chra&iuml;bi&rsquo;s novel <em>The Simple Past</em>, so the subject "Chra&iuml;bi&rsquo;s debut novel" fits perfectly after this introductory modifying phrase.</p><p>Choice A is incorrect. Modifiers and their subjects must go next to each other. The introductory modifier "a coming-of-age story&hellip;colonialism" is describing Chra&iuml;bi&rsquo;s novel, not Morocco. However, this choice places Morocco directly next to that modifier. Choice C is incorrect. Modifiers and their subjects must go next to each other. The introductory modifier "a coming-of-age story&hellip;colonialism" all describes Chra&iuml;bi&rsquo;s novel, not Chra&iuml;bi himself. However, this choice places Chra&iuml;bi directly next to that modifier. Choice D is incorrect. Modifiers and their subjects must go next to each other. The modifier "a coming-of-age story&hellip;" is describing Chra&iuml;bi&rsquo;s novel, so that needs to be the subject immediately after the modifier. This choice adds another modifier that describes Chra&iuml;bi&rsquo;s novel, but then puts "Chra&iuml;bi" himself&mdash;not the novel&mdash;right after that modifier, which doesn&rsquo;t make sense. Chra&iuml;bi wasn&rsquo;t "published two years before" Moroccan independence; his novel <em>The Simple Past</em> was.</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-H005$SATQ$, $SATQ$$SATQ$, $SATQ$fbc11a85-d8ed-4c37-98ea-6c77b50a1530$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5b8f9cf2","external_id":"3bc3e61e-c2c6-441a-ae74-ecc66e630b95","vaultid":"ccebe7cb-4a1c-4832-891b-bd53e7c65fab","uId":"80575ca1-69ff-4d80-961e-b99df57827f8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In the canon of North African literature, Moroccan author Driss Chra&iuml;bi&rsquo;s 1954 novel <em>The Simple Past</em>&nbsp;(<em>Le Pass&eacute; simple</em>) looms large. A coming-of-age story, a social meditation, and a sober gaze into the dark maw of French colonialism, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> interrogates systemic power with memorable intensity.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"875b24e9-6db2-47cf-a232-e45abef0f5df","content":"<p>Morocco gained its independence two years before the publication of Chra&iuml;bi&rsquo;s debut novel, which</p>"},{"id":"d13049f9-1745-4100-a2a7-d03063f8d514","content":"<p>Chra&iuml;bi&rsquo;s debut novel, published two years before Morocco gained its independence,</p>"},{"id":"8d9edecb-7c29-4fc5-a0cc-7e62e591449d","content":"<p>Chra&iuml;bi wrote a debut novel that, published two years before Morocco gained its independence,</p>"},{"id":"27c62977-59ca-42f9-a66a-429bbb992a39","content":"<p>published two years before Morocco gained its independence, Chra&iuml;bi wrote a debut novel that</p>"}],"keys":["d13049f9-1745-4100-a2a7-d03063f8d514"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. Subject-modifier placement requires a modifier and its subject to be next to each other. The subject of the modifier \"a coming-of-age story&hellip;colonialism\" is Chra&iuml;bi&rsquo;s novel <em>The Simple Past</em>, so the subject \"Chra&iuml;bi&rsquo;s debut novel\" fits perfectly after this introductory modifying phrase.</p><p>Choice A is incorrect. Modifiers and their subjects must go next to each other. The introductory modifier \"a coming-of-age story&hellip;colonialism\" is describing Chra&iuml;bi&rsquo;s novel, not Morocco. However, this choice places Morocco directly next to that modifier. Choice C is incorrect. Modifiers and their subjects must go next to each other. The introductory modifier \"a coming-of-age story&hellip;colonialism\" all describes Chra&iuml;bi&rsquo;s novel, not Chra&iuml;bi himself. However, this choice places Chra&iuml;bi directly next to that modifier. Choice D is incorrect. Modifiers and their subjects must go next to each other. The modifier \"a coming-of-age story&hellip;\" is describing Chra&iuml;bi&rsquo;s novel, so that needs to be the subject immediately after the modifier. This choice adds another modifier that describes Chra&iuml;bi&rsquo;s novel, but then puts \"Chra&iuml;bi\" himself&mdash;not the novel&mdash;right after that modifier, which doesn&rsquo;t make sense. Chra&iuml;bi wasn&rsquo;t \"published two years before\" Moroccan independence; his novel <em>The Simple Past</em> was.</p>","parenttemplatename":"OSP-KA-FSS-H005","parenttemplateid":"","templateclusterid":"fbc11a85-d8ed-4c37-98ea-6c77b50a1530","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$5bed774c$SATQ$, $SATQ$c19cd325-f2f3-411c-bb1d-88a70950991f$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Philosopher Peter Kivy was a leading figure in musical <span aria-hidden="true">______</span><span class="sr-only">blank</span> evidenced by his belief that instead of evoking particular emotions, such as sadness or joy,&nbsp; compositions elicit a listener&rsquo;s emotional response to the structure and artistry of the music itself, Kivy&rsquo;s approach to the study of music was decidedly formalist. &nbsp;&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ba2117ec-5f94-4392-92ac-052b28937de3","content":"<p>aesthetics as</p>"},{"id":"36be06fc-da9b-4a66-b5cf-b6031bbd76f3","content":"<p>aesthetics and as</p>"},{"id":"3bc9afd1-ea33-4b5b-a078-84fcae894896","content":"<p>aesthetics<span data-ssml-say-as=\"characters\">,</span> as</p>"},{"id":"0d8357ea-c58e-46aa-a3db-2e194e619645","content":"<p>aesthetics<span data-ssml-say-as=\"characters\">.</span> As</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["0d8357ea-c58e-46aa-a3db-2e194e619645"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence ("Philosopher...aesthetics") and another ("As...formalist"). The long adverbial element "as evidenced...itself" modifies the content in the following clause to support the claim that Kivy&rsquo;s approach was formalist.</p><p>Choice A is incorrect because it results in a run-on sentence. The sentences ("Philosopher...aesthetics" and "As&hellip;formalist") are fused without punctuation and/or a conjunction. Choice B is incorrect. Without a comma preceding it, the conjunction "and" can&rsquo;t be used in this way to join sentences. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5bed774c","external_id":"c19cd325-f2f3-411c-bb1d-88a70950991f","vaultid":null,"uId":"284b4404-bee6-446e-bb6c-9075601891bd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Philosopher Peter Kivy was a leading figure in musical <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> evidenced by his belief that instead of evoking particular emotions, such as sadness or joy,&nbsp; compositions elicit a listener&rsquo;s emotional response to the structure and artistry of the music itself, Kivy&rsquo;s approach to the study of music was decidedly formalist. &nbsp;&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"ba2117ec-5f94-4392-92ac-052b28937de3","content":"<p>aesthetics as</p>"},{"id":"36be06fc-da9b-4a66-b5cf-b6031bbd76f3","content":"<p>aesthetics and as</p>"},{"id":"3bc9afd1-ea33-4b5b-a078-84fcae894896","content":"<p>aesthetics<span data-ssml-say-as=\"characters\">,</span> as</p>"},{"id":"0d8357ea-c58e-46aa-a3db-2e194e619645","content":"<p>aesthetics<span data-ssml-say-as=\"characters\">.</span> As</p>"}],"keys":["0d8357ea-c58e-46aa-a3db-2e194e619645"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (\"Philosopher...aesthetics\") and another (\"As...formalist\"). The long adverbial element \"as evidenced...itself\" modifies the content in the following clause to support the claim that Kivy&rsquo;s approach was formalist.</p><p>Choice A is incorrect because it results in a run-on sentence. The sentences (\"Philosopher...aesthetics\" and \"As&hellip;formalist\") are fused without punctuation and/or a conjunction. Choice B is incorrect. Without a comma preceding it, the conjunction \"and\" can&rsquo;t be used in this way to join sentences. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$5cc85f01$SATQ$, $SATQ$3433622c-fe41-475f-9c1c-0af1cb2cde7c$SATQ$::uuid, $SATQ$339368bc-7100-4143-b7f8-a37b56272854$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>A conceptual artist and designer embraced by both the art world and the fashion <span aria-hidden="true">______</span><span class="sr-only">blank</span> Mary Ping was chosen to curate the exhibition <em>Front Row: Chinese American Designers </em>for the Museum of Chinese in America.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"a0b5a20b-17e1-49dd-abec-5609dbc2c99f","content":"<p>world</p>"},{"id":"d394b9f5-b65f-458a-b411-cbb68f750d14","content":"<p>world:</p>"},{"id":"876372d5-cdfb-455e-9a2f-8eb986d0145a","content":"<p>world;</p>"},{"id":"55b34228-2460-42ab-acc2-f2dc03526ecd","content":"<p>world,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["55b34228-2460-42ab-acc2-f2dc03526ecd"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation between a supplementary phrase and a main clause. This choice correctly uses a comma to mark the boundary between the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;), which describes Mary Ping, and the main clause (&ldquo;Mary&hellip;America&rdquo;). </p><p>Choice A is incorrect because it fails to mark the boundary between the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;) and the main clause (&ldquo;Mary&hellip;America&rdquo;) with appropriate punctuation. Choice B is incorrect because a colon can&rsquo;t be used in this way to join the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;) and the main clause (&ldquo;Mary&hellip;America&rdquo;). In this context, the colon incorrectly suggests that the information in the supplementary phrase is an explanation or amplification of the information in the main clause (Mary Ping being chosen to curate the exhibition), which isn&rsquo;t the case. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to join the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;) and the main clause (&ldquo;Mary&hellip;America&rdquo;). Semicolons are conventionally used to separate two main clauses or to separate items in a complex series. </p>$SATQ$, false, 0, $SATQ$OSP-609-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$776c64ba-8a07-416e-b362-304b56aa9c03$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5cc85f01","external_id":"3433622c-fe41-475f-9c1c-0af1cb2cde7c","vaultid":"339368bc-7100-4143-b7f8-a37b56272854","uId":"92c398f7-565f-4690-9890-cbf47ddcc5ed","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>A conceptual artist and designer embraced by both the art world and the fashion <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Mary Ping was chosen to curate the exhibition <em>Front Row: Chinese American Designers </em>for the Museum of Chinese in America.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"a0b5a20b-17e1-49dd-abec-5609dbc2c99f","content":"<p>world</p>"},{"id":"d394b9f5-b65f-458a-b411-cbb68f750d14","content":"<p>world:</p>"},{"id":"876372d5-cdfb-455e-9a2f-8eb986d0145a","content":"<p>world;</p>"},{"id":"55b34228-2460-42ab-acc2-f2dc03526ecd","content":"<p>world,</p>"}],"keys":["55b34228-2460-42ab-acc2-f2dc03526ecd"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation between a supplementary phrase and a main clause. This choice correctly uses a comma to mark the boundary between the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;), which describes Mary Ping, and the main clause (&ldquo;Mary&hellip;America&rdquo;). </p><p>Choice A is incorrect because it fails to mark the boundary between the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;) and the main clause (&ldquo;Mary&hellip;America&rdquo;) with appropriate punctuation. Choice B is incorrect because a colon can&rsquo;t be used in this way to join the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;) and the main clause (&ldquo;Mary&hellip;America&rdquo;). In this context, the colon incorrectly suggests that the information in the supplementary phrase is an explanation or amplification of the information in the main clause (Mary Ping being chosen to curate the exhibition), which isn&rsquo;t the case. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to join the supplementary phrase (&ldquo;A conceptual artist&hellip;world&rdquo;) and the main clause (&ldquo;Mary&hellip;America&rdquo;). Semicolons are conventionally used to separate two main clauses or to separate items in a complex series. </p>","parenttemplatename":"OSP-609-SEC","parenttemplateid":"","templateclusterid":"776c64ba-8a07-416e-b362-304b56aa9c03","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959339,"updateDate":1691007959339}$SATQ$::jsonb, 1691007959339, 1691007959339),
    ($SATQ$5ee7fb04$SATQ$, $SATQ$374b6ee6-bd5a-40f9-b43a-ba2c333d1945$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In modern plays, actors typically won&rsquo;t acknowledge the <span aria-hidden="true">______</span><span class="sr-only">blank</span> do so breaks the fourth wall, a metaphorical barrier between actors and audiences that allows viewers to suspend the knowledge that they&rsquo;re watching a staged performance.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"47480644-33ea-4d07-94b8-933f40dab4c6","content":"<p>audience. As to</p>"},{"id":"54c19b96-adaa-48e5-9585-ce7e70dd4d61","content":"<p>audience to</p>"},{"id":"35559212-65f3-4061-92a1-d45c85155b12","content":"<p>audience. To</p>"},{"id":"935c9758-7ada-4dc3-ba01-8352e6ce6b1e","content":"<p>audience, to</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["35559212-65f3-4061-92a1-d45c85155b12"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence ("In modern&hellip;audience") and another ("To do&hellip;performance").</p><p>Choice A is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with "as." Choice B is incorrect because it results in a run-on sentence. The sentences ("In modern&hellip;audience" and "To do&hellip;performance") are fused without punctuation and/or a conjunction. Choice D is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5ee7fb04","external_id":"374b6ee6-bd5a-40f9-b43a-ba2c333d1945","vaultid":null,"uId":"e89494b1-179d-4a0c-ab81-cfa1b162876a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In modern plays, actors typically won&rsquo;t acknowledge the <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> do so breaks the fourth wall, a metaphorical barrier between actors and audiences that allows viewers to suspend the knowledge that they&rsquo;re watching a staged performance.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"47480644-33ea-4d07-94b8-933f40dab4c6","content":"<p>audience. As to</p>"},{"id":"54c19b96-adaa-48e5-9585-ce7e70dd4d61","content":"<p>audience to</p>"},{"id":"35559212-65f3-4061-92a1-d45c85155b12","content":"<p>audience. To</p>"},{"id":"935c9758-7ada-4dc3-ba01-8352e6ce6b1e","content":"<p>audience, to</p>"}],"keys":["35559212-65f3-4061-92a1-d45c85155b12"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (\"In modern&hellip;audience\") and another (\"To do&hellip;performance\").</p><p>Choice A is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with \"as.\" Choice B is incorrect because it results in a run-on sentence. The sentences (\"In modern&hellip;audience\" and \"To do&hellip;performance\") are fused without punctuation and/or a conjunction. Choice D is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$5fd86f4b$SATQ$, $SATQ$ccfdec03-a8fb-478a-81c6-3298903b3495$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The ghazal, a poetic form originating in seventh-century Arabic poetry, has an intricate structure. The twentieth-century Kashmiri American poet Agha Shahid Ali explains that each one of a ghazal&rsquo;s couplets, while adhering to the patterns of rhyme (<span lang="ar"><em>qafia</em></span>) and refrain (<span lang="ar"><em>radif</em></span>) established in the poem&rsquo;s opening lines (<span lang="ar"><em>matla</em></span>), <span aria-hidden="true">______</span><span class="sr-only">blank</span> thematically and logically autonomous, resulting in a poem with &ldquo;a stringently formal disunity.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"fb26d9f2-c758-457d-9ecd-ca47a6dddfdb","content":"<p>is</p>"},{"id":"e1e39d5e-69f7-44eb-ba52-3b25adc63c72","content":"<p>were</p>"},{"id":"6771b7e7-b9d9-4eb8-9667-a11bf6477340","content":"<p>have been</p>"},{"id":"0c00d06e-31e5-4318-a5ae-a85c6c2d3500","content":"<p>are</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["fb26d9f2-c758-457d-9ecd-ca47a6dddfdb"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The singular verb "is" agrees in number with the singular subject "each one of a ghazal&rsquo;s couplets." While the prepositional phrase "of a ghazal&rsquo;s couplets" within the subject contains a plural noun, the head of the subject ("each one") is singular, indicating that each individual couplet (not the couplets as a group) is "thematically and logically autonomous," or self-standing.</p><p>Choice B is incorrect because the plural verb "were" doesn&rsquo;t agree in number with the singular subject "each one of a ghazal&rsquo;s couplets." Choice C is incorrect because the plural verb "have been" doesn&rsquo;t agree in number with the singular subject "each one of a ghazal&rsquo;s couplets." Choice D is incorrect because the plural verb "are" doesn&rsquo;t agree in number with the singular subject "each one of a ghazal&rsquo;s couplets."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5fd86f4b","external_id":"ccfdec03-a8fb-478a-81c6-3298903b3495","vaultid":null,"uId":"d2ce4752-e554-4b7d-8b8f-06ee99ab9f43","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The ghazal, a poetic form originating in seventh-century Arabic poetry, has an intricate structure. The twentieth-century Kashmiri American poet Agha Shahid Ali explains that each one of a ghazal&rsquo;s couplets, while adhering to the patterns of rhyme (<span lang=\"ar\"><em>qafia</em></span>) and refrain (<span lang=\"ar\"><em>radif</em></span>) established in the poem&rsquo;s opening lines (<span lang=\"ar\"><em>matla</em></span>), <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> thematically and logically autonomous, resulting in a poem with &ldquo;a stringently formal disunity.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"fb26d9f2-c758-457d-9ecd-ca47a6dddfdb","content":"<p>is</p>"},{"id":"e1e39d5e-69f7-44eb-ba52-3b25adc63c72","content":"<p>were</p>"},{"id":"6771b7e7-b9d9-4eb8-9667-a11bf6477340","content":"<p>have been</p>"},{"id":"0c00d06e-31e5-4318-a5ae-a85c6c2d3500","content":"<p>are</p>"}],"keys":["fb26d9f2-c758-457d-9ecd-ca47a6dddfdb"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The singular verb \"is\" agrees in number with the singular subject \"each one of a ghazal&rsquo;s couplets.\" While the prepositional phrase \"of a ghazal&rsquo;s couplets\" within the subject contains a plural noun, the head of the subject (\"each one\") is singular, indicating that each individual couplet (not the couplets as a group) is \"thematically and logically autonomous,\" or self-standing.</p><p>Choice B is incorrect because the plural verb \"were\" doesn&rsquo;t agree in number with the singular subject \"each one of a ghazal&rsquo;s couplets.\" Choice C is incorrect because the plural verb \"have been\" doesn&rsquo;t agree in number with the singular subject \"each one of a ghazal&rsquo;s couplets.\" Choice D is incorrect because the plural verb \"are\" doesn&rsquo;t agree in number with the singular subject \"each one of a ghazal&rsquo;s couplets.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669213,"updateDate":1743430669213}$SATQ$::jsonb, 1743430669213, 1743430669213),
    ($SATQ$603755a5$SATQ$, $SATQ$6a78cf5a-062e-4db2-9381-1775d8d08c15$SATQ$::uuid, $SATQ$73f7778a-e13b-4f34-99af-a70b845e66ac$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In 1959, marine biologist Dr. Albert Jones founded the Underwater Adventure Seekers, a scuba diving <span aria-hidden="true">______</span><span class="sr-only">blank</span> that is the oldest club for Black divers in the United States and that has helped thousands of diving enthusiasts become certified in the field.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"e88092e2-007d-45cb-a099-58d9d236a962","content":"<p>club</p>"},{"id":"6f5cc2b4-9991-4a49-acfb-a704cb314ca1","content":"<p>club,</p>"},{"id":"845d64af-a347-4a96-8a26-cdfc28fbc1ef","content":"<p>club&mdash;</p>"},{"id":"5a5c0418-34c2-4580-9e12-03127aea60d4","content":"<p>club, and</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["e88092e2-007d-45cb-a099-58d9d236a962"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. &ldquo;That is&hellip;field&rdquo; is an essential supplement, so we should not use punctuation to separate it from &ldquo;scuba diving club.&rdquo;&nbsp;. </p><p>Choice B is incorrect. This choice creates a punctuation error. &ldquo;That is&hellip;field&rdquo; is an essential supplement, so we should not use a comma (or any kind of punctuation) to separate it from &ldquo;scuba diving club.&rdquo;&nbsp;. Choice C is incorrect. This choice creates a punctuation error. &ldquo;That is&hellip;field&rdquo; is an essential supplement, so we should not use a dash (or any kind of punctuation) to separate it from &ldquo;scuba diving club.&rdquo;&nbsp;. Choice D is incorrect. This choice creates a run-on sentence. It makes &ldquo;that is&hellip;United States&rdquo; into an awkward independent clause, but it also makes &ldquo;that has&hellip;field&rdquo; into its own awkward independent clause without the correct punctuation separating it.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-M004$SATQ$, $SATQ$$SATQ$, $SATQ$f0e8193e-db92-465c-836a-84ddf49fd363$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"603755a5","external_id":"6a78cf5a-062e-4db2-9381-1775d8d08c15","vaultid":"73f7778a-e13b-4f34-99af-a70b845e66ac","uId":"c75b2b93-d3d0-4b42-87b3-6a72d64db9ba","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In 1959, marine biologist Dr. Albert Jones founded the Underwater Adventure Seekers, a scuba diving <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> that is the oldest club for Black divers in the United States and that has helped thousands of diving enthusiasts become certified in the field.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"e88092e2-007d-45cb-a099-58d9d236a962","content":"<p>club</p>"},{"id":"6f5cc2b4-9991-4a49-acfb-a704cb314ca1","content":"<p>club,</p>"},{"id":"845d64af-a347-4a96-8a26-cdfc28fbc1ef","content":"<p>club&mdash;</p>"},{"id":"5a5c0418-34c2-4580-9e12-03127aea60d4","content":"<p>club, and</p>"}],"keys":["e88092e2-007d-45cb-a099-58d9d236a962"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. &ldquo;That is&hellip;field&rdquo; is an essential supplement, so we should not use punctuation to separate it from &ldquo;scuba diving club.&rdquo;&nbsp;. </p><p>Choice B is incorrect. This choice creates a punctuation error. &ldquo;That is&hellip;field&rdquo; is an essential supplement, so we should not use a comma (or any kind of punctuation) to separate it from &ldquo;scuba diving club.&rdquo;&nbsp;. Choice C is incorrect. This choice creates a punctuation error. &ldquo;That is&hellip;field&rdquo; is an essential supplement, so we should not use a dash (or any kind of punctuation) to separate it from &ldquo;scuba diving club.&rdquo;&nbsp;. Choice D is incorrect. This choice creates a run-on sentence. It makes &ldquo;that is&hellip;United States&rdquo; into an awkward independent clause, but it also makes &ldquo;that has&hellip;field&rdquo; into its own awkward independent clause without the correct punctuation separating it.&nbsp;</p>","parenttemplatename":"OSP-KA-BOU-M004","parenttemplateid":"","templateclusterid":"f0e8193e-db92-465c-836a-84ddf49fd363","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959359,"updateDate":1691007959359}$SATQ$::jsonb, 1691007959359, 1691007959359),
    ($SATQ$60713427$SATQ$, $SATQ$885313c5-893d-4f59-8ae0-167254da5d81$SATQ$::uuid, $SATQ$74eb6661-73c8-4386-bdbd-34efe647c5d6$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Polyphenols are organic compounds <span aria-hidden="true">______</span><span class="sr-only">blank</span> among their many roles, provide pigment that helps protect plants against ultraviolet radiation from sunlight.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c2a2b27a-54de-4478-958d-2c8adca843e1","content":"<p>that&mdash;</p>"},{"id":"74521f0e-445c-47ab-82fa-eadcece0a167","content":"<p>that;</p>"},{"id":"12424b5f-aac7-402e-a0b6-c374ccfa1730","content":"<p>that,</p>"},{"id":"770a042f-80ee-4d2c-aa14-ac116243359d","content":"<p>that:</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["12424b5f-aac7-402e-a0b6-c374ccfa1730"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;that&rdquo; pairs with the comma after &ldquo;roles&rdquo; to separate the supplementary element &ldquo;among their many roles&rdquo; from the rest of the sentence. This supplementary element functions to clarify that polyphenols have many roles, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because a dash can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence.&nbsp;Choice B is incorrect because a semicolon can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence.&nbsp;Choice D is incorrect because a colon can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence. </p>$SATQ$, false, 0, $SATQ$OSP-784-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$e948ed4d-23e5-4ee2-a83f-701dee762b06$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"60713427","external_id":"885313c5-893d-4f59-8ae0-167254da5d81","vaultid":"74eb6661-73c8-4386-bdbd-34efe647c5d6","uId":"586cbf1d-390b-4ba8-aaff-acc04fa1ea07","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Polyphenols are organic compounds <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> among their many roles, provide pigment that helps protect plants against ultraviolet radiation from sunlight.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"c2a2b27a-54de-4478-958d-2c8adca843e1","content":"<p>that&mdash;</p>"},{"id":"74521f0e-445c-47ab-82fa-eadcece0a167","content":"<p>that;</p>"},{"id":"12424b5f-aac7-402e-a0b6-c374ccfa1730","content":"<p>that,</p>"},{"id":"770a042f-80ee-4d2c-aa14-ac116243359d","content":"<p>that:</p>"}],"keys":["12424b5f-aac7-402e-a0b6-c374ccfa1730"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;that&rdquo; pairs with the comma after &ldquo;roles&rdquo; to separate the supplementary element &ldquo;among their many roles&rdquo; from the rest of the sentence. This supplementary element functions to clarify that polyphenols have many roles, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because a dash can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence.&nbsp;Choice B is incorrect because a semicolon can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence.&nbsp;Choice D is incorrect because a colon can&rsquo;t be paired with a comma to separate the supplementary element from the rest of the sentence. </p>","parenttemplatename":"OSP-784-SEC","parenttemplateid":"","templateclusterid":"e948ed4d-23e5-4ee2-a83f-701dee762b06","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959353,"updateDate":1691007959353}$SATQ$::jsonb, 1691007959353, 1691007959353),
    ($SATQ$60a4c088$SATQ$, $SATQ$2146536a-805d-44d0-907d-c92abeb46074$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>What makes the theremin a unique musical instrument? You play it without touching it. When you place your <span aria-hidden="true">______</span><span class="sr-only">blank</span> the pitch will shift as your hands move through the air.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"dc3060af-d2ce-45b3-b70f-042f411743d4","content":"<p>hand&rsquo;s between the two antenna&rsquo;s,</p>"},{"id":"6ba6a568-c218-4824-8a87-769a4874beda","content":"<p>hands between the two antennas,</p>"},{"id":"1a7c3bf3-1582-46be-a3ba-9c7639d2f342","content":"<p>hands&rsquo; between the two antennas&rsquo;,</p>"},{"id":"5cc06b5c-999a-4ffa-a852-10c9ed905330","content":"<p>hands&rsquo; between the two antennas,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["6ba6a568-c218-4824-8a87-769a4874beda"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of plural nouns in a sentence. The plural noun "hands" and the plural noun "antennas" correctly indicate that two hands are placed between two antennas when playing the theremin.</p><p>Choice A is incorrect because the context requires the plural nouns "hands" and "antennas," not the singular possessive nouns "hand&rsquo;s" and "antenna&rsquo;s." Choice C is incorrect because the context requires the plural nouns "hands" and "antennas," not the plural possessive nouns "hands&rsquo;" and "antennas&rsquo;." Choice D is incorrect because the context requires the plural noun "hands," not the plural possessive noun "hands&rsquo;."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"60a4c088","external_id":"2146536a-805d-44d0-907d-c92abeb46074","vaultid":null,"uId":"753ca994-2e3b-440d-9956-2ec6d3ee50b2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>What makes the theremin a unique musical instrument? You play it without touching it. When you place your <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the pitch will shift as your hands move through the air.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"dc3060af-d2ce-45b3-b70f-042f411743d4","content":"<p>hand&rsquo;s between the two antenna&rsquo;s,</p>"},{"id":"6ba6a568-c218-4824-8a87-769a4874beda","content":"<p>hands between the two antennas,</p>"},{"id":"1a7c3bf3-1582-46be-a3ba-9c7639d2f342","content":"<p>hands&rsquo; between the two antennas&rsquo;,</p>"},{"id":"5cc06b5c-999a-4ffa-a852-10c9ed905330","content":"<p>hands&rsquo; between the two antennas,</p>"}],"keys":["6ba6a568-c218-4824-8a87-769a4874beda"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of plural nouns in a sentence. The plural noun \"hands\" and the plural noun \"antennas\" correctly indicate that two hands are placed between two antennas when playing the theremin.</p><p>Choice A is incorrect because the context requires the plural nouns \"hands\" and \"antennas,\" not the singular possessive nouns \"hand&rsquo;s\" and \"antenna&rsquo;s.\" Choice C is incorrect because the context requires the plural nouns \"hands\" and \"antennas,\" not the plural possessive nouns \"hands&rsquo;\" and \"antennas&rsquo;.\" Choice D is incorrect because the context requires the plural noun \"hands,\" not the plural possessive noun \"hands&rsquo;.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$60dd03bc$SATQ$, $SATQ$3e9880cd-98c2-422e-bba8-c7d45f2ce482$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Located in the northern United States, the Great Lakes Basin contains roughly 35,000 islands. Lake Superior has Grand Island, for example. Lake Michigan has Belle Isle. Lake Huron, though, is home <span aria-hidden="true">______</span><span class="sr-only">blank</span> the largest island of them all: Manitoulin Island. &nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"cf2a0a16-bfbf-45ec-9200-04b476474425","content":"<p>to;</p>"},{"id":"4416605d-d56d-45bb-b945-c1dfb2b87da8","content":"<p>to&mdash;</p>"},{"id":"a38e550e-e348-4ab8-9a2e-fe57ab597f3f","content":"<p>to</p>"},{"id":"9c02d051-904f-4381-80f6-7d728fa35c4e","content":"<p>to,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["a38e550e-e348-4ab8-9a2e-fe57ab597f3f"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation use between a preposition and its complement. No punctuation is needed between the preposition "to" and its complement "the largest island of them all." The complement completes the meaning of the preposition in the phrase "home to the largest island of them all," and any punctuation within it results in an ungrammatical sentence.</p><p>Choice A is incorrect because no punctuation is needed between the preposition and its complement. Choice B is incorrect because no punctuation is needed between the preposition and its complement. Choice D is incorrect because no punctuation is needed between the preposition and its complement.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"60dd03bc","external_id":"3e9880cd-98c2-422e-bba8-c7d45f2ce482","vaultid":null,"uId":"d490fe54-0274-46eb-b0a4-90af62c7b5e6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Located in the northern United States, the Great Lakes Basin contains roughly 35,000 islands. Lake Superior has Grand Island, for example. Lake Michigan has Belle Isle. Lake Huron, though, is home <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the largest island of them all: Manitoulin Island. &nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"cf2a0a16-bfbf-45ec-9200-04b476474425","content":"<p>to;</p>"},{"id":"4416605d-d56d-45bb-b945-c1dfb2b87da8","content":"<p>to&mdash;</p>"},{"id":"a38e550e-e348-4ab8-9a2e-fe57ab597f3f","content":"<p>to</p>"},{"id":"9c02d051-904f-4381-80f6-7d728fa35c4e","content":"<p>to,</p>"}],"keys":["a38e550e-e348-4ab8-9a2e-fe57ab597f3f"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation use between a preposition and its complement. No punctuation is needed between the preposition \"to\" and its complement \"the largest island of them all.\" The complement completes the meaning of the preposition in the phrase \"home to the largest island of them all,\" and any punctuation within it results in an ungrammatical sentence.</p><p>Choice A is incorrect because no punctuation is needed between the preposition and its complement. Choice B is incorrect because no punctuation is needed between the preposition and its complement. Choice D is incorrect because no punctuation is needed between the preposition and its complement.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$61160f0a$SATQ$, $SATQ$f6bd4a4e-3f11-428d-82e6-e1619b5be11c$SATQ$::uuid, $SATQ$b9062a7d-895b-44eb-8eb9-dba5da3485da$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Author Madeline L&rsquo;Engle, <span aria-hidden="true">______</span><span class="sr-only">blank</span> to create a suspenseful tone that draws the reader in, begins her novel <em>A Wrinkle in Time</em> with descriptions of &ldquo;wraithlike shadows&rdquo; and &ldquo;the frenzied lashing of the wind.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"19a596ff-1add-49f9-ade7-10c51db227ea","content":"<p>looked</p>"},{"id":"0a269a3c-c964-4f54-91fd-4195a8aba70d","content":"<p>looks</p>"},{"id":"4a88490b-84a6-408d-90aa-ab9af5a9df6f","content":"<p>is looking</p>"},{"id":"d113a2df-45b4-4fe4-bc14-5b5aa53037ac","content":"<p>looking</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d113a2df-45b4-4fe4-bc14-5b5aa53037ac"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle verb &ldquo;looking&rdquo; is correctly used to form a subordinate clause that describes the intent behind how L&rsquo;Engle begins her novel. </p><p>Choice A is incorrect because the finite past tense verb &ldquo;looked&rdquo; can&rsquo;t be used in this way to form a subordinate clause. Choice B is incorrect because the finite present tense verb &ldquo;looks&rdquo; can&rsquo;t be used in this way to form a subordinate clause. Choice C is incorrect because the finite present progressive tense verb &ldquo;is looking&rdquo; can&rsquo;t be used in this way to form a subordinate clause. </p>$SATQ$, false, 0, $SATQ$OSP-728-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$4f5d0c18-48be-46f7-8f63-6ae144c5d9cf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"61160f0a","external_id":"f6bd4a4e-3f11-428d-82e6-e1619b5be11c","vaultid":"b9062a7d-895b-44eb-8eb9-dba5da3485da","uId":"9adf2077-f8b0-42e9-87cd-cf2ef715242b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Author Madeline L&rsquo;Engle, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> to create a suspenseful tone that draws the reader in, begins her novel <em>A Wrinkle in Time</em> with descriptions of &ldquo;wraithlike shadows&rdquo; and &ldquo;the frenzied lashing of the wind.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"19a596ff-1add-49f9-ade7-10c51db227ea","content":"<p>looked</p>"},{"id":"0a269a3c-c964-4f54-91fd-4195a8aba70d","content":"<p>looks</p>"},{"id":"4a88490b-84a6-408d-90aa-ab9af5a9df6f","content":"<p>is looking</p>"},{"id":"d113a2df-45b4-4fe4-bc14-5b5aa53037ac","content":"<p>looking</p>"}],"keys":["d113a2df-45b4-4fe4-bc14-5b5aa53037ac"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle verb &ldquo;looking&rdquo; is correctly used to form a subordinate clause that describes the intent behind how L&rsquo;Engle begins her novel. </p><p>Choice A is incorrect because the finite past tense verb &ldquo;looked&rdquo; can&rsquo;t be used in this way to form a subordinate clause. Choice B is incorrect because the finite present tense verb &ldquo;looks&rdquo; can&rsquo;t be used in this way to form a subordinate clause. Choice C is incorrect because the finite present progressive tense verb &ldquo;is looking&rdquo; can&rsquo;t be used in this way to form a subordinate clause. </p>","parenttemplatename":"OSP-728-SEC","parenttemplateid":"","templateclusterid":"4f5d0c18-48be-46f7-8f63-6ae144c5d9cf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959349,"updateDate":1691007959349}$SATQ$::jsonb, 1691007959349, 1691007959349),
    ($SATQ$615f001e$SATQ$, $SATQ$e402c9de-ec5c-4fe3-ae02-d6233c202224$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Consider the mechanics of the pinhole camera: light passes through a small hole, resulting in a focused projected image. A ray diagram reveals how this <span aria-hidden="true">______</span><span class="sr-only">blank</span> the hole&rsquo;s small size restricts light to a single ray, all light passing through the hole can only arrive at a single destination, eliminating diffraction and ensuring a clear image.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c7700697-c49c-4883-a6e1-fac2717a8a57","content":"<p>works because</p>"},{"id":"153f2458-7f58-47e1-8087-53f0097d165b","content":"<p>works. Because</p>"},{"id":"56d97e23-78d6-47b1-8ce2-94f946c1a3fd","content":"<p>works, it&rsquo;s because</p>"},{"id":"ce1a1ed6-4017-41af-b555-a7a1c24cbfb9","content":"<p>works: it&rsquo;s because</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["153f2458-7f58-47e1-8087-53f0097d165b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used to correctly mark the boundary between one sentence ("A ray...works") and another ("Because...image").</p><p>Choice A is incorrect because it results in a run-on sentence. The two sentences ("A ray&hellip;works" and "Because&hellip;image") are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect because it results in a comma splice. Since the contraction "it&rsquo;s" creates a main clause, the comma after "single ray" can&rsquo;t be used in this way to mark the boundary between two main clauses ("it&rsquo;s...ray" and "all light&hellip;image").</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"615f001e","external_id":"e402c9de-ec5c-4fe3-ae02-d6233c202224","vaultid":null,"uId":"a70af7d6-2c17-4bca-81ce-30f975096bbe","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Consider the mechanics of the pinhole camera: light passes through a small hole, resulting in a focused projected image. A ray diagram reveals how this <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the hole&rsquo;s small size restricts light to a single ray, all light passing through the hole can only arrive at a single destination, eliminating diffraction and ensuring a clear image.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"c7700697-c49c-4883-a6e1-fac2717a8a57","content":"<p>works because</p>"},{"id":"153f2458-7f58-47e1-8087-53f0097d165b","content":"<p>works. Because</p>"},{"id":"56d97e23-78d6-47b1-8ce2-94f946c1a3fd","content":"<p>works, it&rsquo;s because</p>"},{"id":"ce1a1ed6-4017-41af-b555-a7a1c24cbfb9","content":"<p>works: it&rsquo;s because</p>"}],"keys":["153f2458-7f58-47e1-8087-53f0097d165b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used to correctly mark the boundary between one sentence (\"A ray...works\") and another (\"Because...image\").</p><p>Choice A is incorrect because it results in a run-on sentence. The two sentences (\"A ray&hellip;works\" and \"Because&hellip;image\") are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect because it results in a comma splice. Since the contraction \"it&rsquo;s\" creates a main clause, the comma after \"single ray\" can&rsquo;t be used in this way to mark the boundary between two main clauses (\"it&rsquo;s...ray\" and \"all light&hellip;image\").</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323049,"updateDate":1730147323049}$SATQ$::jsonb, 1730147323049, 1730147323049),
    ($SATQ$62120607$SATQ$, $SATQ$b80deb69-694b-483f-bf34-a0354855c351$SATQ$::uuid, $SATQ$f2b4c6a9-78bd-4b55-a65b-8dc6f5aa6779$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>From afar, African American fiber artist Bisa Butler&rsquo;s portraits look like paintings, their depictions of human faces, bodies, and clothing so intricate that it seems only a fine brush could have rendered them. When viewed up close, however, the portraits reveal themselves to be <span aria-hidden="true">______</span><span class="sr-only">blank</span> stitching barely visible among the thousands of pieces of printed, microcut fabric.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"4ed8ef50-fbc0-488a-a245-b54485d5b1cf","content":"<p>quilts, and the</p>"},{"id":"fb41b52d-93ca-4f43-8842-f459b6e4d591","content":"<p>quilts, the</p>"},{"id":"c61eaa51-c9f7-45c4-a33e-3df45a5665c8","content":"<p>quilts; the</p>"},{"id":"da11a7f9-a408-4ee7-9a43-abf77a11581d","content":"<p>quilts. The</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["fb41b52d-93ca-4f43-8842-f459b6e4d591"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is punctuation use between a main clause and a supplementary phrase. This choice correctly uses a comma to mark the boundary between the main clause (&ldquo;the portraits...quilts&rdquo;) and the supplementary noun phrase (&ldquo;the stitching...fabric&rdquo;) that provides a further description of how the portraits can be identified as quilts. </p><p>Choice A is incorrect. A comma and the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join a main clause and a supplementary noun phrase. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to join a main clause and a supplementary noun phrase. Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;the stitching.&rdquo; </p>$SATQ$, false, 0, $SATQ$OSP-649-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$fc0605de-684f-45b6-ab32-c0a1102652ef$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"62120607","external_id":"b80deb69-694b-483f-bf34-a0354855c351","vaultid":"f2b4c6a9-78bd-4b55-a65b-8dc6f5aa6779","uId":"66d64970-ce52-4228-be7f-4b5afaf702fd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>From afar, African American fiber artist Bisa Butler&rsquo;s portraits look like paintings, their depictions of human faces, bodies, and clothing so intricate that it seems only a fine brush could have rendered them. When viewed up close, however, the portraits reveal themselves to be <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> stitching barely visible among the thousands of pieces of printed, microcut fabric.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"4ed8ef50-fbc0-488a-a245-b54485d5b1cf","content":"<p>quilts, and the</p>"},{"id":"fb41b52d-93ca-4f43-8842-f459b6e4d591","content":"<p>quilts, the</p>"},{"id":"c61eaa51-c9f7-45c4-a33e-3df45a5665c8","content":"<p>quilts; the</p>"},{"id":"da11a7f9-a408-4ee7-9a43-abf77a11581d","content":"<p>quilts. The</p>"}],"keys":["fb41b52d-93ca-4f43-8842-f459b6e4d591"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is punctuation use between a main clause and a supplementary phrase. This choice correctly uses a comma to mark the boundary between the main clause (&ldquo;the portraits...quilts&rdquo;) and the supplementary noun phrase (&ldquo;the stitching...fabric&rdquo;) that provides a further description of how the portraits can be identified as quilts. </p><p>Choice A is incorrect. A comma and the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join a main clause and a supplementary noun phrase. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to join a main clause and a supplementary noun phrase. Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;the stitching.&rdquo; </p>","parenttemplatename":"OSP-649-SEC","parenttemplateid":"","templateclusterid":"fc0605de-684f-45b6-ab32-c0a1102652ef","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$626a1642$SATQ$, $SATQ$c9621282-e14b-469a-a221-70a4156b72f3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>As a behavioral economist, Katy Milkman of the University of Pennsylvania recognizes that people sometimes make irrational economic decisions. Milkman&rsquo;s research can thus address anomalies that neoclassical economic <span aria-hidden="true">______</span><span class="sr-only">blank</span> assume that people are consistently rational decision-makers&mdash;cannot explain.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"cf0e9235-f8d5-4cd5-9ca8-3a901db73f47","content":"<p>models<span data-ssml-say-as=\"characters\">&mdash;</span>which&nbsp;</p>"},{"id":"ff1aae12-94d5-47d3-ab14-61afa189b449","content":"<p>models<span data-ssml-say-as=\"characters\">,</span> which</p>"},{"id":"da027a09-04df-46bf-8356-180b18241627","content":"<p>models which</p>"},{"id":"f48bbb04-66e8-4651-a439-8151b3e699b4","content":"<p>models which<span data-ssml-say-as=\"characters\">&mdash;</span> &nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["cf0e9235-f8d5-4cd5-9ca8-3a901db73f47"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. The dashes after "models" and "decision-makers" correctly separate the supplementary element "which assume that people are consistently rational decision-makers" from the rest of the sentence. This punctuation indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice B is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it interrupts the sentence at an illogical and grammatically incoherent point. The dash should be placed before "which," not after it, to mark the beginning of the supplementary element.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"626a1642","external_id":"c9621282-e14b-469a-a221-70a4156b72f3","vaultid":null,"uId":"130388d4-2fe1-4bc1-a0ef-167506cd9130","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>As a behavioral economist, Katy Milkman of the University of Pennsylvania recognizes that people sometimes make irrational economic decisions. Milkman&rsquo;s research can thus address anomalies that neoclassical economic <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> assume that people are consistently rational decision-makers&mdash;cannot explain.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"cf0e9235-f8d5-4cd5-9ca8-3a901db73f47","content":"<p>models<span data-ssml-say-as=\"characters\">&mdash;</span>which&nbsp;</p>"},{"id":"ff1aae12-94d5-47d3-ab14-61afa189b449","content":"<p>models<span data-ssml-say-as=\"characters\">,</span> which</p>"},{"id":"da027a09-04df-46bf-8356-180b18241627","content":"<p>models which</p>"},{"id":"f48bbb04-66e8-4651-a439-8151b3e699b4","content":"<p>models which<span data-ssml-say-as=\"characters\">&mdash;</span> &nbsp;</p>"}],"keys":["cf0e9235-f8d5-4cd5-9ca8-3a901db73f47"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. The dashes after \"models\" and \"decision-makers\" correctly separate the supplementary element \"which assume that people are consistently rational decision-makers\" from the rest of the sentence. This punctuation indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice B is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it interrupts the sentence at an illogical and grammatically incoherent point. The dash should be placed before \"which,\" not after it, to mark the beginning of the supplementary element.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$64a40675$SATQ$, $SATQ$064399ea-9935-485f-8710-e93223bc074b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 1953, a fellow performer tripped on legendary jazz musician Dizzy Gillespie&rsquo;s trumpet, bending its bell upward. When Gillespie tested the damaged instrument, he realized that he <span aria-hidden="true">______</span><span class="sr-only">blank</span> sound of a bent bell over that of a straight one.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"28b2d666-4cbc-40b5-ad06-f403d7f27f50","content":"<p>preferred; the</p>"},{"id":"68ae6b5b-679a-4ec8-aa92-a26565e023b9","content":"<p>preferred the</p>"},{"id":"9364e0ab-fc16-4932-b5dc-0dba544f13f6","content":"<p>preferred, the</p>"},{"id":"26c4d355-fb3e-4e80-97dc-461d4cea6ee1","content":"<p>preferred. The</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["68ae6b5b-679a-4ec8-aa92-a26565e023b9"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is punctuation use between a verb and its object. No punctuation is needed between the verb "preferred" and its object "the sound of a bent bell over that of a straight one." The object helps complete the idea of the verb&mdash;in this case, it explains what type of sound Gillespie preferred&mdash;and any punctuation between the two results in an ungrammatical sentence.</p><p>Choice A is incorrect because no punctuation is needed between the verb and its object. Choice C is incorrect because no punctuation is needed between the verb and its object. Choice D is incorrect because no punctuation is needed between the verb and its object.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"64a40675","external_id":"064399ea-9935-485f-8710-e93223bc074b","vaultid":null,"uId":"f6398c3f-3994-4ec2-a4dd-5f6b7bf71bec","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 1953, a fellow performer tripped on legendary jazz musician Dizzy Gillespie&rsquo;s trumpet, bending its bell upward. When Gillespie tested the damaged instrument, he realized that he <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> sound of a bent bell over that of a straight one.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"28b2d666-4cbc-40b5-ad06-f403d7f27f50","content":"<p>preferred; the</p>"},{"id":"68ae6b5b-679a-4ec8-aa92-a26565e023b9","content":"<p>preferred the</p>"},{"id":"9364e0ab-fc16-4932-b5dc-0dba544f13f6","content":"<p>preferred, the</p>"},{"id":"26c4d355-fb3e-4e80-97dc-461d4cea6ee1","content":"<p>preferred. The</p>"}],"keys":["68ae6b5b-679a-4ec8-aa92-a26565e023b9"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is punctuation use between a verb and its object. No punctuation is needed between the verb \"preferred\" and its object \"the sound of a bent bell over that of a straight one.\" The object helps complete the idea of the verb&mdash;in this case, it explains what type of sound Gillespie preferred&mdash;and any punctuation between the two results in an ungrammatical sentence.</p><p>Choice A is incorrect because no punctuation is needed between the verb and its object. Choice C is incorrect because no punctuation is needed between the verb and its object. Choice D is incorrect because no punctuation is needed between the verb and its object.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$667a0587$SATQ$, $SATQ$9b5e2c20-4871-4a3c-b1d8-c48dd0e64690$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In early 1700s England, it was legal for shops to sell prints of artists&rsquo; engravings without the artists&rsquo; permission. This changed in <span data-ssml-say-as="date">1735</span> with the passage of the Engravers&rsquo; Copyright <span aria-hidden="true">______</span><span class="sr-only">blank</span> gave engravers control over the distribution and sale of all prints made from their designs.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ac8a6de1-3793-44fd-b2e1-54f2ff50eed5","content":"<p>Act<span data-ssml-say-as=\"characters\">,</span> which</p>"},{"id":"21afed40-f92e-4731-85df-4227fb07ff00","content":"<p>Act<span data-ssml-say-as=\"characters\">;</span> which</p>"},{"id":"9082c597-c765-4989-85fa-946ff2d404e7","content":"<p>Act<span data-ssml-say-as=\"characters\">.</span> Which</p>"},{"id":"fb5accf9-583c-4b5b-8090-fd6fb9b3d33a","content":"<p>Act&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ac8a6de1-3793-44fd-b2e1-54f2ff50eed5"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of punctuation between a main clause and a supplementary element. In this choice, the comma is used correctly to mark the boundary between the main clause ("This...Act") and the supplementary relative clause ("which...designs") that provides additional information about the Engravers&rsquo; Copyright Act.</p><p>Choice B is incorrect because a semicolon can&rsquo;t be used in this way to mark the boundary between a main clause and a supplementary relative clause. A semicolon is conventionally used to join two main clauses, and "which...designs" isn&rsquo;t a main clause. Choice C is incorrect because it results in a rhetorically unacceptable sentence fragment. Choice D is incorrect. Joining the main clause and the additional information about the Engravers&rsquo; Copyright Act ("gave...designs") without the comma and relative pronoun "which" results in a confusing and ungrammatical sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"667a0587","external_id":"9b5e2c20-4871-4a3c-b1d8-c48dd0e64690","vaultid":null,"uId":"baaeedbc-a3cc-4e55-95f1-f4ae4133de75","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In early 1700s England, it was legal for shops to sell prints of artists&rsquo; engravings without the artists&rsquo; permission. This changed in <span data-ssml-say-as=\"date\">1735</span> with the passage of the Engravers&rsquo; Copyright <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> gave engravers control over the distribution and sale of all prints made from their designs.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"ac8a6de1-3793-44fd-b2e1-54f2ff50eed5","content":"<p>Act<span data-ssml-say-as=\"characters\">,</span> which</p>"},{"id":"21afed40-f92e-4731-85df-4227fb07ff00","content":"<p>Act<span data-ssml-say-as=\"characters\">;</span> which</p>"},{"id":"9082c597-c765-4989-85fa-946ff2d404e7","content":"<p>Act<span data-ssml-say-as=\"characters\">.</span> Which</p>"},{"id":"fb5accf9-583c-4b5b-8090-fd6fb9b3d33a","content":"<p>Act&nbsp;</p>"}],"keys":["ac8a6de1-3793-44fd-b2e1-54f2ff50eed5"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of punctuation between a main clause and a supplementary element. In this choice, the comma is used correctly to mark the boundary between the main clause (\"This...Act\") and the supplementary relative clause (\"which...designs\") that provides additional information about the Engravers&rsquo; Copyright Act.</p><p>Choice B is incorrect because a semicolon can&rsquo;t be used in this way to mark the boundary between a main clause and a supplementary relative clause. A semicolon is conventionally used to join two main clauses, and \"which...designs\" isn&rsquo;t a main clause. Choice C is incorrect because it results in a rhetorically unacceptable sentence fragment. Choice D is incorrect. Joining the main clause and the additional information about the Engravers&rsquo; Copyright Act (\"gave...designs\") without the comma and relative pronoun \"which\" results in a confusing and ungrammatical sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$674e59a3$SATQ$, $SATQ$05f74e82-e82f-4979-b23e-6aa8533f1b21$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Following her debut album release in 2002, Mexican singer-songwriter Natalia Lafourcade quickly shot to fame. By 2023, she <span aria-hidden="true">______</span><span class="sr-only">blank</span> one of the most celebrated musicians in Latin America, having released twelve albums and won seventeen Latin Grammy awards&mdash;more than any other female artist in history.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"9abfef31-413c-4dab-9b8e-2e0d4e9c1caa","content":"<p>will become</p>"},{"id":"46b49e33-9f29-4e57-8cd0-2a0064584231","content":"<p>becomes</p>"},{"id":"6d34d3d0-d2f9-4f9d-8a5b-f6600cc6593b","content":"<p>will have become</p>"},{"id":"5588c053-784f-4417-b1a7-ca5ade152e4e","content":"<p>had become</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5588c053-784f-4417-b1a7-ca5ade152e4e"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense in a sentence. The past perfect tense indicates an action that was completed before another past action. In this choice, the past perfect verb &ldquo;had become,&rdquo; together with the supplemental phrase &ldquo;by 2023,&rdquo; indicates that Lafourcade earned her status as one of the most celebrated musicians in Latin America before 2023.</p><p>Choice A is incorrect because the future tense &ldquo;will become&rdquo; doesn&rsquo;t indicate that Lafourcade earned her celebrated status before 2023. Choice B is incorrect because the present tense &ldquo;becomes&rdquo; doesn&rsquo;t indicate that Lafourcade earned her celebrated status before 2023. Choice C is incorrect because the future perfect tense &ldquo;will have become&rdquo; doesn&rsquo;t indicate that Lafourcade earned her celebrated status by 2023.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"674e59a3","external_id":"05f74e82-e82f-4979-b23e-6aa8533f1b21","vaultid":null,"uId":"25900cd1-97e6-4cc7-86f8-1742d1c43502","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Following her debut album release in 2002, Mexican singer-songwriter Natalia Lafourcade quickly shot to fame. By 2023, she <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> one of the most celebrated musicians in Latin America, having released twelve albums and won seventeen Latin Grammy awards&mdash;more than any other female artist in history.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"9abfef31-413c-4dab-9b8e-2e0d4e9c1caa","content":"<p>will become</p>"},{"id":"46b49e33-9f29-4e57-8cd0-2a0064584231","content":"<p>becomes</p>"},{"id":"6d34d3d0-d2f9-4f9d-8a5b-f6600cc6593b","content":"<p>will have become</p>"},{"id":"5588c053-784f-4417-b1a7-ca5ade152e4e","content":"<p>had become</p>"}],"keys":["5588c053-784f-4417-b1a7-ca5ade152e4e"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense in a sentence. The past perfect tense indicates an action that was completed before another past action. In this choice, the past perfect verb &ldquo;had become,&rdquo; together with the supplemental phrase &ldquo;by 2023,&rdquo; indicates that Lafourcade earned her status as one of the most celebrated musicians in Latin America before 2023.</p><p>Choice A is incorrect because the future tense &ldquo;will become&rdquo; doesn&rsquo;t indicate that Lafourcade earned her celebrated status before 2023. Choice B is incorrect because the present tense &ldquo;becomes&rdquo; doesn&rsquo;t indicate that Lafourcade earned her celebrated status before 2023. Choice C is incorrect because the future perfect tense &ldquo;will have become&rdquo; doesn&rsquo;t indicate that Lafourcade earned her celebrated status by 2023.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771167,"updateDate":1776362771167}$SATQ$::jsonb, 1776362771167, 1776362771167),
    ($SATQ$67614549$SATQ$, $SATQ$3488a4f0-8e4c-4665-b117-1c6b4757dd9f$SATQ$::uuid, $SATQ$276e5f05-ea5b-44f7-9c7c-d90c2fb01304$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>After winning the 1860 presidential election, Abraham Lincoln appointed Edward Bates, Salmon P. Chase, and William H. Seward to his cabinet. Lincoln&rsquo;s decision was surprising, since each of these men had run against him, but historians have praised it, noting that Lincoln <span aria-hidden="true">______</span><span class="sr-only">blank</span> his rivals&rsquo; diverse talents to strengthen his administration.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"1800e007-acc8-4fe8-9482-2a68939d916d","content":"<p>has leveraged</p>"},{"id":"bf32f432-b5ce-4c66-842b-366e9090c86a","content":"<p>is leveraging</p>"},{"id":"30a82211-f2bf-43e6-83b9-1512ef8da477","content":"<p>will leverage</p>"},{"id":"bed50c58-80ed-42e8-8339-46c5d17e8d71","content":"<p>leveraged</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["bed50c58-80ed-42e8-8339-46c5d17e8d71"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The subject of the verb is &ldquo;Lincoln,&rdquo; and the first sentence tells us that we&rsquo;re talking about something that Abraham Lincoln did in 1860. So the simple past tense &ldquo;leveraged&rdquo; fits the logic of the text. </p><p>Choice A is incorrect. This choice creates a tense issue. &ldquo;Has leveraged&rdquo; is the present perfect tense, which is used for an action that began in the past and continues into the present. Lincoln started leveraging his rivals&rsquo; talents in 1860&mdash;it&rsquo;s definitely not still happening today. So the present perfect tense isn&rsquo;t appropriate. Choice B is incorrect. This choice creates a tense issue. &ldquo;Is leveraging&rdquo; is the present tense, but Lincoln leveraged his rivals&rsquo; talents in 1860, so the present tense isn&rsquo;t appropriate. Choice C is incorrect. This choice creates a tense issue. &ldquo;Will leverage&rdquo; is the future tense, but Lincoln leveraged his rivals&rsquo; talents in 1860, so the future tense isn&rsquo;t appropriate. </p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-M004$SATQ$, $SATQ$$SATQ$, $SATQ$390e3f6a-37e8-4858-9e7e-8c569b3d9bcf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"67614549","external_id":"3488a4f0-8e4c-4665-b117-1c6b4757dd9f","vaultid":"276e5f05-ea5b-44f7-9c7c-d90c2fb01304","uId":"fa5f31db-5855-4640-8245-a2f2794a78b0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>After winning the 1860 presidential election, Abraham Lincoln appointed Edward Bates, Salmon P. Chase, and William H. Seward to his cabinet. Lincoln&rsquo;s decision was surprising, since each of these men had run against him, but historians have praised it, noting that Lincoln <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> his rivals&rsquo; diverse talents to strengthen his administration.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"1800e007-acc8-4fe8-9482-2a68939d916d","content":"<p>has leveraged</p>"},{"id":"bf32f432-b5ce-4c66-842b-366e9090c86a","content":"<p>is leveraging</p>"},{"id":"30a82211-f2bf-43e6-83b9-1512ef8da477","content":"<p>will leverage</p>"},{"id":"bed50c58-80ed-42e8-8339-46c5d17e8d71","content":"<p>leveraged</p>"}],"keys":["bed50c58-80ed-42e8-8339-46c5d17e8d71"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The subject of the verb is &ldquo;Lincoln,&rdquo; and the first sentence tells us that we&rsquo;re talking about something that Abraham Lincoln did in 1860. So the simple past tense &ldquo;leveraged&rdquo; fits the logic of the text. </p><p>Choice A is incorrect. This choice creates a tense issue. &ldquo;Has leveraged&rdquo; is the present perfect tense, which is used for an action that began in the past and continues into the present. Lincoln started leveraging his rivals&rsquo; talents in 1860&mdash;it&rsquo;s definitely not still happening today. So the present perfect tense isn&rsquo;t appropriate. Choice B is incorrect. This choice creates a tense issue. &ldquo;Is leveraging&rdquo; is the present tense, but Lincoln leveraged his rivals&rsquo; talents in 1860, so the present tense isn&rsquo;t appropriate. Choice C is incorrect. This choice creates a tense issue. &ldquo;Will leverage&rdquo; is the future tense, but Lincoln leveraged his rivals&rsquo; talents in 1860, so the future tense isn&rsquo;t appropriate. </p>","parenttemplatename":"OSP-KA-FSS-M004","parenttemplateid":"","templateclusterid":"390e3f6a-37e8-4858-9e7e-8c569b3d9bcf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$67667d72$SATQ$, $SATQ$c6925857-6ee5-4d22-bcad-1f31a98fa419$SATQ$::uuid, $SATQ$c90674b2-7e48-4970-85c0-5b5004bcf53f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Humans were long thought to have begun occupying the Peruvian settlement of Machu Picchu between 1440 and 1450 CE. However, a team led by anthropologist Dr. Richard Burger used accelerator mass spectrometry to uncover evidence that it was occupied <span aria-hidden="true">______</span><span class="sr-only">blank</span> 1420 CE, according to Burger, humans were likely inhabiting the area.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"5da7ba0a-11d6-4787-8e74-2ef58040b4f9","content":"<p>earlier. In</p>"},{"id":"0b92f258-ac9d-4490-b641-a0cb8df180bb","content":"<p>earlier, in</p>"},{"id":"2bb2bcaf-01bf-4da0-89f5-e8f9508c9dc5","content":"<p>earlier, which in</p>"},{"id":"13b61958-f4c4-4ad2-b119-4999120434f0","content":"<p>earlier in</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["5da7ba0a-11d6-4787-8e74-2ef58040b4f9"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (&ldquo;However...earlier&rdquo;) and another (&ldquo;In...area&rdquo;). The supplementary phrase &ldquo;in 1420 CE&rdquo; modifies &ldquo;humans,&rdquo; the subject of the third sentence. </p><p>Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Moreover, the subordinating conjunction &ldquo;which&rdquo; creates a confusing and illogical sentence that suggests that the supplementary phrase beginning with &ldquo;in&rdquo; modifies the previous information (&ldquo;However...earlier&rdquo;) rather than the information that follows.&nbsp;Choice D is incorrect because it results in a run-on sentence. The sentences (&ldquo;However...earlier&rdquo; and &ldquo;in...area&rdquo;) are fused without punctuation and/or a conjunction. </p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-M001$SATQ$, $SATQ$$SATQ$, $SATQ$b7746700-15e1-4ee1-b61e-590925eb6bd0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"67667d72","external_id":"c6925857-6ee5-4d22-bcad-1f31a98fa419","vaultid":"c90674b2-7e48-4970-85c0-5b5004bcf53f","uId":"73980d03-d5cf-4670-ae3f-765a5b5be6e1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Humans were long thought to have begun occupying the Peruvian settlement of Machu Picchu between 1440 and 1450 CE. However, a team led by anthropologist Dr. Richard Burger used accelerator mass spectrometry to uncover evidence that it was occupied <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> 1420 CE, according to Burger, humans were likely inhabiting the area.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"5da7ba0a-11d6-4787-8e74-2ef58040b4f9","content":"<p>earlier. In</p>"},{"id":"0b92f258-ac9d-4490-b641-a0cb8df180bb","content":"<p>earlier, in</p>"},{"id":"2bb2bcaf-01bf-4da0-89f5-e8f9508c9dc5","content":"<p>earlier, which in</p>"},{"id":"13b61958-f4c4-4ad2-b119-4999120434f0","content":"<p>earlier in</p>"}],"keys":["5da7ba0a-11d6-4787-8e74-2ef58040b4f9"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (&ldquo;However...earlier&rdquo;) and another (&ldquo;In...area&rdquo;). The supplementary phrase &ldquo;in 1420 CE&rdquo; modifies &ldquo;humans,&rdquo; the subject of the third sentence. </p><p>Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Moreover, the subordinating conjunction &ldquo;which&rdquo; creates a confusing and illogical sentence that suggests that the supplementary phrase beginning with &ldquo;in&rdquo; modifies the previous information (&ldquo;However...earlier&rdquo;) rather than the information that follows.&nbsp;Choice D is incorrect because it results in a run-on sentence. The sentences (&ldquo;However...earlier&rdquo; and &ldquo;in...area&rdquo;) are fused without punctuation and/or a conjunction. </p>","parenttemplatename":"OSP-KA-BOU-M001","parenttemplateid":"","templateclusterid":"b7746700-15e1-4ee1-b61e-590925eb6bd0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959359,"updateDate":1691007959359}$SATQ$::jsonb, 1691007959359, 1691007959359),
    ($SATQ$684b8bd2$SATQ$, $SATQ$ca6aad86-e39f-46be-8997-426a80aafeaf$SATQ$::uuid, $SATQ$a911bf06-4ac2-49c0-aa5d-a2fa031cd3b9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Far from being modern inventions, <span aria-hidden="true">______</span><span class="sr-only">blank</span> more than 5,000 years ago.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"8d99071b-5969-4f8b-bcc0-51ed73106190","content":"<p>Sumerians in ancient Mesopotamia used drinking straws</p>"},{"id":"fd8892bd-91c3-448a-b89a-6bc4535be2b0","content":"<p>drinking straws were used by Sumerians in ancient Mesopotamia</p>"},{"id":"9b414631-579c-457a-9920-1c434cb75d7e","content":"<p>the use of drinking straws by Sumerians in ancient Mesopotamia happened</p>"},{"id":"a9f69dee-6617-4615-9a7a-67dc4cba1e4a","content":"<p>ancient Mesopotamia was home to Sumerians who used drinking straws</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["fd8892bd-91c3-448a-b89a-6bc4535be2b0"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; must be describing &ldquo;drinking straws,&rdquo; because those are the only possible inventions in this sentence. </p><p>Choice A is incorrect. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; can&rsquo;t be describing &ldquo;Sumerians,&rdquo; because they are a group of people, not an invention. Choice C is incorrect. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; can&rsquo;t be describing &ldquo;the use of drinking straws,&rdquo; because it is not &ldquo;the use&rdquo; of drinking straws that is an invention&mdash;it is the drinking straws themselves. Choice D is incorrect. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; can&rsquo;t be describing &ldquo;Ancient Mesopotamia,&rdquo; because that is a place, not an invention. </p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-M008$SATQ$, $SATQ$$SATQ$, $SATQ$472eb75e-2e33-4684-96e2-701d9889e00d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"684b8bd2","external_id":"ca6aad86-e39f-46be-8997-426a80aafeaf","vaultid":"a911bf06-4ac2-49c0-aa5d-a2fa031cd3b9","uId":"71973fe9-dfc6-48cc-a0e5-c6d29d9753ee","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Far from being modern inventions, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> more than 5,000 years ago.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"8d99071b-5969-4f8b-bcc0-51ed73106190","content":"<p>Sumerians in ancient Mesopotamia used drinking straws</p>"},{"id":"fd8892bd-91c3-448a-b89a-6bc4535be2b0","content":"<p>drinking straws were used by Sumerians in ancient Mesopotamia</p>"},{"id":"9b414631-579c-457a-9920-1c434cb75d7e","content":"<p>the use of drinking straws by Sumerians in ancient Mesopotamia happened</p>"},{"id":"a9f69dee-6617-4615-9a7a-67dc4cba1e4a","content":"<p>ancient Mesopotamia was home to Sumerians who used drinking straws</p>"}],"keys":["fd8892bd-91c3-448a-b89a-6bc4535be2b0"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; must be describing &ldquo;drinking straws,&rdquo; because those are the only possible inventions in this sentence. </p><p>Choice A is incorrect. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; can&rsquo;t be describing &ldquo;Sumerians,&rdquo; because they are a group of people, not an invention. Choice C is incorrect. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; can&rsquo;t be describing &ldquo;the use of drinking straws,&rdquo; because it is not &ldquo;the use&rdquo; of drinking straws that is an invention&mdash;it is the drinking straws themselves. Choice D is incorrect. Modifiers and their subjects must go next to each other. The modifier &ldquo;far from being modern inventions&rdquo; can&rsquo;t be describing &ldquo;Ancient Mesopotamia,&rdquo; because that is a place, not an invention. </p>","parenttemplatename":"OSP-KA-FSS-M008","parenttemplateid":"","templateclusterid":"472eb75e-2e33-4684-96e2-701d9889e00d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$6997261f$SATQ$, $SATQ$45ea795f-d4f5-4fbc-bd5c-0406ebd32a52$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In 2009, researchers determined that pottery fragments from a cave in China were close to 18,000 years old. These are some of the oldest <span aria-hidden="true">______</span><span class="sr-only">blank</span> of pottery ever found.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"68ee3c62-5a2c-47c5-9e47-e24305da68d6","content":"<p>pieces:</p>"},{"id":"a2956a3f-3f8c-486b-97c7-d1256023335e","content":"<p>pieces,</p>"},{"id":"60c4d186-a0ea-4f7c-9ea9-4e34ba350cd2","content":"<p>pieces</p>"},{"id":"58026ec7-662d-4540-9444-ffe604c52e0d","content":"<p>pieces&mdash;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["60c4d186-a0ea-4f7c-9ea9-4e34ba350cd2"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation use between a noun and a prepositional phrase. No punctuation is needed between the noun "pieces" and the prepositional phrase "of pottery." The prepositional phrase provides essential information about what kind of pieces were found, so it shouldn&rsquo;t be separated from the rest of the noun phrase ("some of the oldest pieces") with punctuation.</p><p>Choice A is incorrect because no punctuation is needed between the noun phrase "some of the oldest pieces" and the prepositional phrase "of pottery." Choice B is incorrect because no punctuation is needed between the noun phrase "some of the oldest pieces" and the prepositional phrase "of pottery." Choice D is incorrect because no punctuation is needed between the noun phrase "some of the oldest pieces" and the prepositional phrase "of pottery."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6997261f","external_id":"45ea795f-d4f5-4fbc-bd5c-0406ebd32a52","vaultid":null,"uId":"e540b9f7-3225-4138-bc4f-3dd4ed78f43f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In 2009, researchers determined that pottery fragments from a cave in China were close to 18,000 years old. These are some of the oldest <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> of pottery ever found.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"68ee3c62-5a2c-47c5-9e47-e24305da68d6","content":"<p>pieces:</p>"},{"id":"a2956a3f-3f8c-486b-97c7-d1256023335e","content":"<p>pieces,</p>"},{"id":"60c4d186-a0ea-4f7c-9ea9-4e34ba350cd2","content":"<p>pieces</p>"},{"id":"58026ec7-662d-4540-9444-ffe604c52e0d","content":"<p>pieces&mdash;</p>"}],"keys":["60c4d186-a0ea-4f7c-9ea9-4e34ba350cd2"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation use between a noun and a prepositional phrase. No punctuation is needed between the noun \"pieces\" and the prepositional phrase \"of pottery.\" The prepositional phrase provides essential information about what kind of pieces were found, so it shouldn&rsquo;t be separated from the rest of the noun phrase (\"some of the oldest pieces\") with punctuation.</p><p>Choice A is incorrect because no punctuation is needed between the noun phrase \"some of the oldest pieces\" and the prepositional phrase \"of pottery.\" Choice B is incorrect because no punctuation is needed between the noun phrase \"some of the oldest pieces\" and the prepositional phrase \"of pottery.\" Choice D is incorrect because no punctuation is needed between the noun phrase \"some of the oldest pieces\" and the prepositional phrase \"of pottery.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$69f031ab$SATQ$, $SATQ$b76bc994-bb77-47fa-be8f-b73de6f5a5d9$SATQ$::uuid, $SATQ$d554d2e7-e22a-4548-bad4-92f111d76269$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While exploring Nevada&rsquo;s Gypsum Cave in 1930, Seneca and Abenaki archaeologist Bertha Parker made her most famous discovery: the skull of a now-extinct ground sloth (<em>Nothrotheriops shastensis</em>) alongside human-made tools. Parker&rsquo;s crucial finding was the first <span aria-hidden="true">______</span><span class="sr-only">blank</span> humans in North America as far back as 10,000 years ago.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d272d3f2-8765-40b8-ab1d-74e7ec8cb83a","content":"<p>places</p>"},{"id":"9ce414df-fb77-4e26-a21a-f41ba341dd1c","content":"<p>placed</p>"},{"id":"3122767a-9d07-4c9d-98ca-d732cc14a809","content":"<p>place</p>"},{"id":"809f74a2-07d7-4e94-809e-fc819fefea00","content":"<p>to place</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["809f74a2-07d7-4e94-809e-fc819fefea00"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The object for the verb "was" is "first," and "to place" is acting as a modifier for "first." What was the finding? It was "the first." The first to do what? The first "to place humans in North America" 10,000 years ago. When a verb serves as a modifier within a noun phrase, it must be nonfinite (i.e., not conjugated to a specific subject). The infinitive form "to place" is the only nonfinite option among the choices that makes sense in context.</p><p>Choice A is incorrect. The object for the verb "was" is "first," and "places" is acting as a modifier for "first." What was the thing that Parker&rsquo;s finding did? What was it the first to do? Place humans in North America 10,000 years ago. When a verb acts as a modifier, it must be nonfinite (i.e., not conjugated to a specific subject), but "places" is a finite form of the verb. Choice B is incorrect. The object for the verb "was" is "first," and "placed" is acting to modify "first." What was it that Parker&rsquo;s finding was the first to do? Place humans in North America 10,000 years ago. When a verb acts as a modifier, it must be nonfinite (i.e., not conjugated to a specific subject), but "placed" is a finite form. "Placed" can also be a past participle, but that wouldn&rsquo;t make sense here because the meaning of "the first placed humans" would be unclear. Choice C is incorrect. The object for the verb "was" is "first," and "place" is modifying "first." What was the thing that Parker&rsquo;s finding did? What was it the first to do? Place humans in North America. When a verb acts as a modifier, it must be nonfinite (i.e., not conjugated to a specific subject), but "place" is a finite form of the verb. Additionally, "place" can&rsquo;t serve as a noun here, because it results in an illogical sentence (the "finding" wasn&rsquo;t "the first place").</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-M010$SATQ$, $SATQ$$SATQ$, $SATQ$38b17abb-922b-40b3-803a-a76d8d6e3e48$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"69f031ab","external_id":"b76bc994-bb77-47fa-be8f-b73de6f5a5d9","vaultid":"d554d2e7-e22a-4548-bad4-92f111d76269","uId":"46acb5ed-b486-41e4-ab5f-4a04a636e6a6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While exploring Nevada&rsquo;s Gypsum Cave in 1930, Seneca and Abenaki archaeologist Bertha Parker made her most famous discovery: the skull of a now-extinct ground sloth (<em>Nothrotheriops shastensis</em>) alongside human-made tools. Parker&rsquo;s crucial finding was the first <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> humans in North America as far back as 10,000 years ago.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d272d3f2-8765-40b8-ab1d-74e7ec8cb83a","content":"<p>places</p>"},{"id":"9ce414df-fb77-4e26-a21a-f41ba341dd1c","content":"<p>placed</p>"},{"id":"3122767a-9d07-4c9d-98ca-d732cc14a809","content":"<p>place</p>"},{"id":"809f74a2-07d7-4e94-809e-fc819fefea00","content":"<p>to place</p>"}],"keys":["809f74a2-07d7-4e94-809e-fc819fefea00"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The object for the verb \"was\" is \"first,\" and \"to place\" is acting as a modifier for \"first.\" What was the finding? It was \"the first.\" The first to do what? The first \"to place humans in North America\" 10,000 years ago. When a verb serves as a modifier within a noun phrase, it must be nonfinite (i.e., not conjugated to a specific subject). The infinitive form \"to place\" is the only nonfinite option among the choices that makes sense in context.</p><p>Choice A is incorrect. The object for the verb \"was\" is \"first,\" and \"places\" is acting as a modifier for \"first.\" What was the thing that Parker&rsquo;s finding did? What was it the first to do? Place humans in North America 10,000 years ago. When a verb acts as a modifier, it must be nonfinite (i.e., not conjugated to a specific subject), but \"places\" is a finite form of the verb. Choice B is incorrect. The object for the verb \"was\" is \"first,\" and \"placed\" is acting to modify \"first.\" What was it that Parker&rsquo;s finding was the first to do? Place humans in North America 10,000 years ago. When a verb acts as a modifier, it must be nonfinite (i.e., not conjugated to a specific subject), but \"placed\" is a finite form. \"Placed\" can also be a past participle, but that wouldn&rsquo;t make sense here because the meaning of \"the first placed humans\" would be unclear. Choice C is incorrect. The object for the verb \"was\" is \"first,\" and \"place\" is modifying \"first.\" What was the thing that Parker&rsquo;s finding did? What was it the first to do? Place humans in North America. When a verb acts as a modifier, it must be nonfinite (i.e., not conjugated to a specific subject), but \"place\" is a finite form of the verb. Additionally, \"place\" can&rsquo;t serve as a noun here, because it results in an illogical sentence (the \"finding\" wasn&rsquo;t \"the first place\").</p>","parenttemplatename":"OSP-KA-FSS-M010","parenttemplateid":"","templateclusterid":"38b17abb-922b-40b3-803a-a76d8d6e3e48","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$6b49f5f1$SATQ$, $SATQ$07e644e3-0de6-4c39-8041-74cd3d1d1b67$SATQ$::uuid, $SATQ$9bf5fae5-3c8a-4e4e-9325-7e63545b9126$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In 1727, dramatist Lewis Theobald presented a new play, <em>Double Falsehood</em>, at a London theater. Theobald claimed that his drama was based on a little-known play by William Shakespeare, <em>Cardenio</em>. Many, including poet Alexander Pope, were <span aria-hidden="true">______</span><span class="sr-only">blank</span> historians have determined that Shakespeare&rsquo;s company did perform a play called <em>Cardenio</em> in 1613.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"5b2af13d-6e3f-436b-9ecf-63003b9a9f43","content":"<p>skeptical but</p>"},{"id":"5a267bdc-de83-4439-a984-b262598eff54","content":"<p>skeptical, but</p>"},{"id":"40e96440-6fe6-4219-ba8b-ec3231bd53eb","content":"<p>skeptical,</p>"},{"id":"6a4ab271-257c-4aa3-a07a-7b689994206f","content":"<p>skeptical</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["5a267bdc-de83-4439-a984-b262598eff54"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. There are two independent clauses in the sentence, each with a subject and a verb: "many...were skeptical" and "historians have determined&hellip;." These clauses can be grammatically joined by a comma and the coordinating conjunction "but."</p><p>Choice A is incorrect. This choice results in a run-on sentence, which occurs when two independent clauses are joined without punctuation. Two independent clauses can&rsquo;t be joined by just the coordinating conjunction "but." A comma would also be required. Choice C is incorrect. This choice creates a punctuation error called a comma splice. This sentence contains two independent clauses ("Many&hellip;were skeptical" and "historians have determined&hellip;"). A comma alone can&rsquo;t join two independent clauses. That requires a comma and a coordinating conjunction. Choice D is incorrect. This choice results in a run-on sentence, which occurs when two independent clauses are joined without punctuation. This sentence contains two independent clauses ("Many&hellip;were skeptical" and "historians have determined&hellip;"), which need to be either joined by a semicolon, joined by a comma and a coordinating conjunction, or separated by a period.</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-M005$SATQ$, $SATQ$$SATQ$, $SATQ$abb39bd7-540a-494a-a3a7-257bf255928c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6b49f5f1","external_id":"07e644e3-0de6-4c39-8041-74cd3d1d1b67","vaultid":"9bf5fae5-3c8a-4e4e-9325-7e63545b9126","uId":"85220857-451d-4b1d-9609-5c153d970126","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In 1727, dramatist Lewis Theobald presented a new play, <em>Double Falsehood</em>, at a London theater. Theobald claimed that his drama was based on a little-known play by William Shakespeare, <em>Cardenio</em>. Many, including poet Alexander Pope, were <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> historians have determined that Shakespeare&rsquo;s company did perform a play called <em>Cardenio</em> in 1613.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"5b2af13d-6e3f-436b-9ecf-63003b9a9f43","content":"<p>skeptical but</p>"},{"id":"5a267bdc-de83-4439-a984-b262598eff54","content":"<p>skeptical, but</p>"},{"id":"40e96440-6fe6-4219-ba8b-ec3231bd53eb","content":"<p>skeptical,</p>"},{"id":"6a4ab271-257c-4aa3-a07a-7b689994206f","content":"<p>skeptical</p>"}],"keys":["5a267bdc-de83-4439-a984-b262598eff54"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. There are two independent clauses in the sentence, each with a subject and a verb: \"many...were skeptical\" and \"historians have determined&hellip;.\" These clauses can be grammatically joined by a comma and the coordinating conjunction \"but.\"</p><p>Choice A is incorrect. This choice results in a run-on sentence, which occurs when two independent clauses are joined without punctuation. Two independent clauses can&rsquo;t be joined by just the coordinating conjunction \"but.\" A comma would also be required. Choice C is incorrect. This choice creates a punctuation error called a comma splice. This sentence contains two independent clauses (\"Many&hellip;were skeptical\" and \"historians have determined&hellip;\"). A comma alone can&rsquo;t join two independent clauses. That requires a comma and a coordinating conjunction. Choice D is incorrect. This choice results in a run-on sentence, which occurs when two independent clauses are joined without punctuation. This sentence contains two independent clauses (\"Many&hellip;were skeptical\" and \"historians have determined&hellip;\"), which need to be either joined by a semicolon, joined by a comma and a coordinating conjunction, or separated by a period.</p>","parenttemplatename":"OSP-KA-BOU-M005","parenttemplateid":"","templateclusterid":"abb39bd7-540a-494a-a3a7-257bf255928c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959359,"updateDate":1691007959359}$SATQ$::jsonb, 1691007959359, 1691007959359),
    ($SATQ$6bc907c9$SATQ$, $SATQ$26616194-2880-4427-af14-e3eb1ac1703d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Novelist Jane Austen greatly admired the work of Fanny Burney, a popular English author. In fact, scholars believe that a passage from the last chapter of <em>Cecilia</em>, a 1782 novel by Burney, likely inspired the title of one of <span aria-hidden="true">______</span><span class="sr-only">blank</span> <em>Pride and Prejudice</em>.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"bc2d9859-927c-49d1-a80b-0edc72651821","content":"<p>Austen&rsquo;s most famous novels,</p>"},{"id":"167e328a-359e-4487-8bea-4e22210b324b","content":"<p>Austens&rsquo; most famous novels&rsquo;,</p>"},{"id":"9e8c6e1a-dfaa-41b4-8432-6e760e643ab3","content":"<p>Austens most famous novels,</p>"},{"id":"e428924b-9f02-4701-ad82-5218af4411bf","content":"<p>Austen&rsquo;s most famous novel&rsquo;s,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["bc2d9859-927c-49d1-a80b-0edc72651821"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of plural and possessive nouns. The singular possessive proper noun "Austen&rsquo;s" and the plural noun "novels" correctly indicates that Austen wrote multiple novels that were famous.</p><p>Choice B is incorrect because the context requires the singular possessive proper noun "Austen&rsquo;s" and the plural noun "novels," not the plural possessive nouns "Austens&rsquo;" and "novels&rsquo;." Choice C is incorrect because the context requires the singular possessive proper noun "Austen&rsquo;s," not the plural proper noun "Austens." Choice D is incorrect because the context requires the plural noun "novels," not the singular possessive noun "novel&rsquo;s."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6bc907c9","external_id":"26616194-2880-4427-af14-e3eb1ac1703d","vaultid":null,"uId":"7701af11-37aa-4f5f-864c-cc67cee7b3d0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Novelist Jane Austen greatly admired the work of Fanny Burney, a popular English author. In fact, scholars believe that a passage from the last chapter of <em>Cecilia</em>, a 1782 novel by Burney, likely inspired the title of one of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> <em>Pride and Prejudice</em>.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"bc2d9859-927c-49d1-a80b-0edc72651821","content":"<p>Austen&rsquo;s most famous novels,</p>"},{"id":"167e328a-359e-4487-8bea-4e22210b324b","content":"<p>Austens&rsquo; most famous novels&rsquo;,</p>"},{"id":"9e8c6e1a-dfaa-41b4-8432-6e760e643ab3","content":"<p>Austens most famous novels,</p>"},{"id":"e428924b-9f02-4701-ad82-5218af4411bf","content":"<p>Austen&rsquo;s most famous novel&rsquo;s,</p>"}],"keys":["bc2d9859-927c-49d1-a80b-0edc72651821"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of plural and possessive nouns. The singular possessive proper noun \"Austen&rsquo;s\" and the plural noun \"novels\" correctly indicates that Austen wrote multiple novels that were famous.</p><p>Choice B is incorrect because the context requires the singular possessive proper noun \"Austen&rsquo;s\" and the plural noun \"novels,\" not the plural possessive nouns \"Austens&rsquo;\" and \"novels&rsquo;.\" Choice C is incorrect because the context requires the singular possessive proper noun \"Austen&rsquo;s,\" not the plural proper noun \"Austens.\" Choice D is incorrect because the context requires the plural noun \"novels,\" not the singular possessive noun \"novel&rsquo;s.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051)
